  // Assistant/application/closeNote/autoFill.js
  function getServiceNowWindow(rootWindow) {
    return (rootWindow?.g_form ? rootWindow : null) || rootWindow?.top?.frames?.gsft_main || rootWindow?.frames?.gsft_main || rootWindow || window;
  }
  function readField(gForm, fieldName) {
    try {
      return cleanText(gForm?.getValue?.(fieldName) || gForm?.getDisplayValue?.(fieldName) || "");
    } catch {
      return "";
    }
  }
  function getSolutionText(context = {}, gForm = null) {
    const contextValue = cleanText(
      context.solution || context.u_solution || context.resolution || context.u_resolution || context.resolution_notes || context.resolutionNotes || context.solution_notes || context.solutionNotes
    );
    if (contextValue) return contextValue;
    const fields = [
      "solution",
      "u_solution",
      "resolution",
      "u_resolution",
      "resolution_notes",
      "u_resolution_notes",
      "solution_notes",
      "u_solution_notes"
    ];
    for (const field of fields) {
      const value = readField(gForm, field);
      if (value) return value;
    }
    return "";
  }
  function isTicketNumber(value) {
    return /^(INC|REQ|RITM|SCTASK|TASK)\d+$/i.test(String(value || "").trim());
  }
  function cleanName(name) {
    const n = cleanText(name || "");
    if (!n || isTicketNumber(n)) return "";
    return n;
  }
  function firstName(name) {
    const n = cleanName(name);
    return n ? n.split(/\s+/)[0] : "User";
  }
  function detectClosureType(stateValue, stateDisplay) {
    const s = String(stateDisplay || "").toLowerCase().replace(/[_-]+/g, " ");
    if (/cancel/.test(s)) return "cancelled";
    if (/incomplete|not complete|uncomplete/.test(s)) return "incomplete";
    if (/complete|resolved|closed/.test(s)) return "complete";
    if (stateValue === "4") return "incomplete";
    if (stateValue === "7") return "cancelled";
    if (stateValue === "3") return "complete";
    return "complete";
  }
  function detectRequestType(allText) {
    if (/return|restitution|stock|logistic|logistics/.test(allText)) return "return";
    if (/delivery|deliver|livraison|handover|equipment|device|laptop|iphone|smartphone|headset|webcam|dock|docking|keyboard|mouse/.test(allText)) return "delivery";
    if (/license|licence|access|permission|account|rights|software|application/.test(allText)) return "access";
    if (/broken|issue|problem|fault|not working|repair|replace|replacement|swap/.test(allText)) return "incident";
    return "generic";
  }
  function buildSmartCloseNote({ context, gForm, rootWindow }) {
    const snWindow = getServiceNowWindow(rootWindow);
    const ticket = cleanText(context?.ticketNumber || context?.recordNumber || readField(gForm, "number") || "this ticket");
    const requestedFor = cleanName(context?.requestedFor) || cleanName(context?.requested_for) || cleanName(readField(gForm, "requested_for")) || cleanName(readField(gForm, "caller_id")) || cleanName(readField(gForm, "u_affected_end_user")) || cleanName(readField(gForm, "opened_by")) || "User";
    const agent = cleanName(context?.assignedToDisplay) || cleanName(readField(gForm, "assigned_to")) || cleanName(snWindow?.NOW?.user_display_name) || "IT Support Team";
    const stateValue = cleanText(context?.state || readField(gForm, "state"));
    const stateDisplay = cleanText(context?.stateDisplay || readField(gForm, "state")) || stateValue;
    const allText = [
      cleanText(context?.shortDescription || readField(gForm, "short_description")),
      cleanText(context?.description || readField(gForm, "description")),
      cleanText(context?.configurationItem || readField(gForm, "cmdb_ci")),
      cleanText(context?.assignmentGroup || readField(gForm, "assignment_group")),
      stateDisplay
    ].join(" ").toLowerCase();
    const requestType = detectRequestType(allText);
    const closureType = detectClosureType(stateValue, stateDisplay);
    const dynamicResolution = (() => {
      if (closureType === "cancelled") return "This task has been cancelled and no further action will be taken at this stage.";
      if (closureType === "incomplete") {
        if (requestType === "delivery") return "This task has been closed as incomplete because the delivery could not be completed with the available information or current conditions.";
        if (requestType === "return") return "This task has been closed as incomplete because the equipment return could not be completed at this stage.";
        return "This task has been closed as incomplete because the required action could not be completed at this stage.";
      }
      if (requestType === "delivery") return "Your requested IT equipment has been prepared and processed successfully.";
      if (requestType === "return") return "The equipment return has been processed successfully.";
      if (requestType === "access") return "The requested access, license, or software-related action has been checked and processed successfully.";
      if (requestType === "incident") return "The reported issue has been reviewed and the necessary action has been completed.";
      return "The requested action has been completed successfully.";
    })();
    const statusSentence = closureType === "cancelled" ? `We would like to inform you that your task ${ticket} has been cancelled.` : closureType === "incomplete" ? `We would like to inform you that your task ${ticket} has been closed as incomplete.` : `We would like to inform you that your task ${ticket} has been successfully resolved.`;
    return [
      `Dear ${firstName(requestedFor)},`,
      "",
      statusSentence,
      "",
      dynamicResolution,
      "",
      "If you continue to experience any issues or require further assistance, please do not hesitate to contact us.",
      "",
      "Kind regards,",
      agent
    ].join("\n");
  }
  function setNativeValue(snWindow, el, value) {
    const proto = el.tagName === "TEXTAREA" ? snWindow.HTMLTextAreaElement.prototype : snWindow.HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
    if (setter) setter.call(el, value);
    else el.value = value;
    el.dispatchEvent(new snWindow.Event("input", { bubbles: true }));
    el.dispatchEvent(new snWindow.Event("change", { bubbles: true }));
    el.dispatchEvent(new snWindow.Event("blur", { bubbles: true }));
  }
  function tryDomWrite({ rootWindow, table, field, value }) {
    const snWindow = getServiceNowWindow(rootWindow);
    const doc = snWindow?.document;
    if (!doc) return false;
    const selectors = [
      `[name="${field}"]`,
      `textarea[name="${field}"]`,
      `input[name="${field}"]`,
      `#${field}`,
      `#${table}.${field}`,
      `#sys_display\\.${table}\\.${field}`
    ];
    for (const sel of selectors) {
      const el = doc.querySelector(sel);
      if (!el) continue;
      setNativeValue(snWindow, el, value);
      return true;
    }
    return false;
  }
  function autoFillCloseNote({ context, settings, rootWindow = getRootWindow() }) {
    if (!context) return { ok: false, kind: "no-context" };
    try {
      const bestGForm = getBestGForm(rootWindow);
      const gForm = bestGForm?.gForm;
      const existing = cleanText(readField(gForm, "close_notes") || readField(gForm, "u_close_notes"));
      if (existing) {
        return { ok: true, kind: "already-set" };
      }
      const solutionText = getSolutionText(context, gForm);
      const groups = getTemplateGroups(settings);
      const { template } = selectCloseNoteTemplate(groups.close_note || [], context, context);
      const templateText = solutionText ? "" : cleanText(template ? renderTemplate(template, { context, settings })?.body || "" : "");
      const smartText = solutionText ? "" : cleanText(buildSmartCloseNote({ context, gForm, rootWindow }));
      const text2 = cleanText(solutionText || templateText || smartText);
      if (!text2) return { ok: false, kind: "no-template" };
      const inserted = insertRenderedTemplate(
        { body: text2, category: "close_note", target: "close_notes" },
        context
      );
      const templateId = solutionText ? "existing-solution" : template?.id || "smart-close-note";
      const source = solutionText ? "solution" : templateText ? "template" : "smart-generated";
      if (inserted?.ok) {
        return {
          ok: true,
          kind: "filled",
          templateId,
          source,
          targetField: inserted.targetField
        };
      }
      const fallbackField = typeof gForm?.setValue === "function" ? "close_notes" : "";
      if (fallbackField) {
        gForm.setValue(fallbackField, text2);
        return {
          ok: true,
          kind: "filled",
          templateId,
          source,
          targetField: fallbackField
        };
      }
      const domOkClose = tryDomWrite({ rootWindow, table: cleanText(gForm?.getTableName?.() || context?.table || ""), field: "close_notes", value: text2 });
      const domOkUClose = domOkClose ? false : tryDomWrite({ rootWindow, table: cleanText(gForm?.getTableName?.() || context?.table || ""), field: "u_close_notes", value: text2 });
      if (domOkClose || domOkUClose) {
        return {
          ok: true,
          kind: "filled",
          templateId,
          source,
          targetField: domOkClose ? "close_notes" : "u_close_notes"
        };
      }
      return { ok: false, kind: "no-target" };
    } catch (error2) {
      return { ok: false, kind: "error", error: error2 };
    }
  }

  // Assistant/application/templates/selection.js
  function isDraftCapableCategory(category = "") {
    return ["email", "appointment"].includes(cleanText(category));
  }
  function getSafeCategory(requestedCategory = "", groups = {}) {
    const category = cleanText(requestedCategory);
    if (category === "resolution") return "close_note";
    if (category === "internal") return "work_note";
    return groups[category] ? category : "";
  }
  function mergeResolvedUser(currentUser = {}, resolvedUser = {}) {
    const merged = {
      firstName: resolvedUser.firstName || currentUser.firstName || "",
      lastName: resolvedUser.lastName || currentUser.lastName || "",
      fullName: resolvedUser.fullName || currentUser.fullName || "",
      email: resolvedUser.email || currentUser.email || "",
      phone: resolvedUser.phone || currentUser.phone || ""
    };
    if (!merged.fullName) {
      merged.fullName = [merged.firstName, merged.lastName].filter(Boolean).join(" ").trim();
    }
    return merged;
  }
  function selectSmartTemplateForCategory(state, settings, requestedCategory = state.ui.activeCategory) {
    const groups = getTemplateGroups(settings);
    const categories = getCategories();
    const fallbackCategory = categories.find((category) => groups[category.id]?.length)?.id || categories[0]?.id || "email";
    const normalizedRequestedCategory = getSafeCategory(requestedCategory, groups);
    const activeCategory = groups[normalizedRequestedCategory]?.length ? normalizedRequestedCategory : fallbackCategory;
    const ticketContext = detectContext(state.context || {});
    let selectedTemplate = null;
    let selectedTemplateId = "";
    let emailSelection = null;
    if (activeCategory === "work_note") {
      const selection = selectWorkNoteTemplate(groups.work_note || [], state.context || {}, ticketContext);
      selectedTemplate = selection.template;
      selectedTemplateId = selection.templateId;
    } else if (activeCategory === "reminder") {
      const templates2 = groups.reminder || [];
      const emailSelection2 = selectEmailTemplate(groups.email || [], state.context || {}, ticketContext);
      const suggestedReminderId = emailSelection2.templateId ? `reminder_${emailSelection2.templateId}` : "";
      const preferredId = state.ui.selectedTemplates?.reminder || "";
      selectedTemplateId = templates2.some((template) => template.id === preferredId) ? preferredId : templates2.some((template) => template.id === suggestedReminderId) ? suggestedReminderId : templates2[0]?.id || "";
      selectedTemplate = templates2.find((template) => template.id === selectedTemplateId) || templates2[0] || null;
    } else if (activeCategory === "close_note") {
      const selection = selectCloseNoteTemplate(groups.close_note || [], state.context || {}, ticketContext);
      selectedTemplate = selection.template;
      selectedTemplateId = selection.templateId;
    } else if (activeCategory === "appointment") {
      const templates2 = groups.appointment || [];
      selectedTemplate = templates2[0] || null;
      selectedTemplateId = selectedTemplate?.id || "";
    } else {
      const selection = selectEmailTemplate(groups.email || [], state.context || {}, ticketContext);
      emailSelection = selection;
      selectedTemplate = selection.template;
      selectedTemplateId = selection.templateId;
    }
    if (!selectedTemplateId) {
      selectedTemplateId = getFirstTemplateId(activeCategory, settings);
    }
    const templates = groups[activeCategory] || [];
    if (!templates.some((template) => template.id === selectedTemplateId)) {
      selectedTemplateId = getFirstTemplateId(activeCategory, settings);
    }
    setActiveCategory(state, activeCategory);
    setSelectedTemplate(state, activeCategory, selectedTemplateId);
    selectedTemplate = templates.find((template) => template.id === selectedTemplateId) || selectedTemplate || null;
    return {
      groups,
      categories,
      activeCategory,
      templates,
      selectedTemplateId,
      selectedTemplate,
      emailSelection
    };
  }
  function ensureTemplateSelection(state, settings) {
    return selectSmartTemplateForCategory(state, settings, state.ui.activeCategory);
  }
  function resolveTemplateSelection(state, settings, requestedCategory = state.ui.activeCategory) {
    if (requestedCategory === state.ui.activeCategory) {
      return ensureTemplateSelection(state, settings);
    }
    return selectSmartTemplateForCategory(state, settings, requestedCategory);
  }

  // Assistant/application/email/renderedSelection.js
  function looksLikeTicket(value) {
    return TICKET_NUMBER_PATTERN.test(cleanText(value));
  }
  async function getRenderedSelection({
    state,
    settings,
    logger,
    rootWindow,
    hydrateUser = false,
    categoryOverride
  }) {
    const baseContext = state.context || getCurrentContext(rootWindow);
    if (!baseContext?.supported) {
      return {
        renderedTemplate: null,
        selection: resolveTemplateSelection(state, settings, categoryOverride),
        emailSuggestions: []
      };
    }
    const currentCi = getCurrentCmdbCi(rootWindow);
    let context = {
      ...baseContext,
      configurationItem: !looksLikeTicket(currentCi.display) ? currentCi.display || currentCi.value || "" : "",
      configurationItemDisplay: !looksLikeTicket(currentCi.display) ? currentCi.display || currentCi.value || "" : "",
      configurationItemValue: !looksLikeTicket(currentCi.value) ? currentCi.value || currentCi.display || "" : ""
    };
    if (hydrateUser) {
      const resolvedUser = await resolveUserForContext(context, state, settings, logger);
      const mergedUser = mergeResolvedUser(context?.user, resolvedUser);
      if (mergedUser.email !== context?.user?.email || mergedUser.fullName !== context?.user?.fullName || mergedUser.firstName !== context?.user?.firstName || mergedUser.lastName !== context?.user?.lastName) {
        context = { ...context, user: mergedUser };
        state.context = context;
      }
    }
    if (context.configurationItem && !looksLikeTicket(context.configurationItem)) {
      state.context = {
        ...state.context || {},
        configurationItem: context.configurationItem,
        configurationItemDisplay: context.configurationItemDisplay || context.configurationItem,
        configurationItemValue: context.configurationItemValue || context.configurationItem
      };
    }
    const selection = resolveTemplateSelection(state, settings, categoryOverride);
    const renderedTemplate = selection.selectedTemplate ? renderTemplate(selection.selectedTemplate, { context, settings }) : null;
    const emailSuggestions = selection.activeCategory === "email" && selection.emailSelection?.ambiguous ? (selection.emailSelection.candidates || []).slice(0, 3).map((candidate) => {
      const template = selection.templates.find((item) => item.id === candidate.templateId);
      if (!template) return null;
      const rendered = renderTemplate(template, { context, settings });
      return {
        templateId: candidate.templateId,
        score: candidate.score,
        label: template.label,
        subject: rendered?.subject || "",
        body: rendered?.body || ""
      };
    }).filter(Boolean) : [];
    return { renderedTemplate, selection, emailSuggestions };
  }

  // Assistant/templates/validators.js
  var PLACEHOLDER_PATTERN = /\{\{[^}]+\}\}/g;
  function validateCloseNotes(closeNotesText) {
    const issues = [];
    const text2 = cleanText(closeNotesText || "");
    if (!text2) {
      issues.push("Close notes are empty. Add a close note before resolving.");
    }
    const unresolvedMatches = text2.match(PLACEHOLDER_PATTERN) || [];
    if (unresolvedMatches.length > 0) {
      issues.push(
        `Close notes contain ${unresolvedMatches.length} unresolved placeholder(s): ${unresolvedMatches.slice(0, 3).join(", ")}`
      );
    }
    return issues;
  }
  function validateDraftComposeTemplate(renderedTemplate) {
    const issues = [];
    const recipient = String(renderedTemplate?.recipient || "").trim();
    const subject = String(renderedTemplate?.subject || "").trim();
    const body = String(renderedTemplate?.body || "").trim();
    if (!recipient) issues.push("Recipient email is empty");
    if (!subject) issues.push("Subject is empty");
    if (!body) issues.push("Body is empty");
    const unresolvedSubject = PLACEHOLDER_PATTERN.test(subject);
    PLACEHOLDER_PATTERN.lastIndex = 0;
    const unresolvedBody = PLACEHOLDER_PATTERN.test(body);
    PLACEHOLDER_PATTERN.lastIndex = 0;
    if (unresolvedSubject || unresolvedBody) {
      issues.push("Some placeholders were not resolved (check {{...}} in red)");
    }
    return issues;
  }

  // Assistant/application/clipboard/copyWithToast.js
  var DEFAULT_FAILURE_MESSAGE = "Auto-copy was blocked by the browser. Please copy manually (Ctrl+C).";
  async function copyWithToast({
    value,
    hostDocument,
    successToast = false,
    failureToast = DEFAULT_FAILURE_MESSAGE
  } = {}) {
    if (!value) return false;
    let copied = false;
    try {
      copied = await copyToClipboard(value, hostDocument);
    } catch {
      copied = false;
    }
    if (copied) {
      if (successToast && hostDocument) {
        showToast(hostDocument, { message: successToast, tone: "info" });
      }
      return true;
    }
    if (failureToast && hostDocument) {
      showToast(hostDocument, { message: failureToast, tone: "warning" });
    }
    return false;
  }

  // Assistant/application/email/logArtifacts.js
  function logGeneratedArtifacts(renderedTemplate, context, settings, logger) {
    if (!renderedTemplate || !isDraftCapableCategory(renderedTemplate.category)) {
      return;
    }
    const commentResult = insertEmailComment(renderedTemplate, context);
    if (!commentResult.ok) {
      logger?.warn("email comment could not be written", {
        templateId: renderedTemplate?.id || ""
      });
    }
    const workNote = buildWorkNoteForEmailAction(renderedTemplate, context, settings);
    logger?.info("work note generated", {
      ticketNumber: context?.ticketNumber || context?.recordNumber || "",
      templateId: renderedTemplate?.id || "",
      source: "email-action"
    });
    const workNoteResult = insertWorkNote(workNote, context);
    if (!workNoteResult.ok) {
      logger?.warn("work note could not be written", {
        templateId: renderedTemplate?.id || ""
      });
    }
  }

  // Assistant/application/email/runDraftFlow.js
  async function runDraftFlow({
    state,
    settings,
    logger,
    rootWindow,
    categoryOverride = "email",
    cacheDraftContent,
    resetDraftContentCache,
    confirmValidationIssues,
    notify
  }) {
    resetDraftContentCache?.();
    const { renderedTemplate, selection } = await getRenderedSelection({
      state,
      settings,
      logger,
      rootWindow,
      hydrateUser: true,
      categoryOverride
    });
    if (!renderedTemplate || !isDraftCapableCategory(renderedTemplate.category)) {
      throw new Error("Draft is only available for email-like templates");
    }
    const emailTemplate = renderedTemplate.category === "email" ? renderedTemplate : { ...renderedTemplate, category: "email" };
    if (settings.toggles.autoCopyToClipboard) {
      await copyWithToast({
        value: emailTemplate.clipboardText,
        hostDocument: state.host.document
      });
    }
    logGeneratedArtifacts(emailTemplate, state.context, settings, logger);
    const validationIssues = validateDraftComposeTemplate(emailTemplate);
    if (validationIssues.length > 0) {
      cacheDraftContent?.(emailTemplate, "", true);
      const userConfirmed = await confirmValidationIssues?.(validationIssues);
      if (!userConfirmed) {
        return false;
      }
    }
    const result = openDraft(emailTemplate);
    if (!result.ok) {
      cacheDraftContent?.(emailTemplate, result.mailto || "", true);
      notify?.(`Draft creation failed: ${result.error || "Unable to build compose URL"}`, "error");
      return false;
    }
    cacheDraftContent?.(emailTemplate, result.opened ? "" : result.mailto || "", !result.opened);
    if (!result.opened) {
      notify?.("Draft created. Open it manually from the panel.", "info");
      return false;
    }
    logger?.info("template rendered successfully", { templateId: selection.selectedTemplateId });
    return true;
  }

  // Assistant/application/email/runReminderFlow.js
