        const assetTag = cleanText(ciResult?.asset_tag);
        const configurationItem = assetTag || name;
        setCurrentCmdbCi(rootWindow, sysId, name);
        const previousContext = { ...state.context || {} };
        store.dispatch(setContext, {
          ...previousContext,
          selected_ci_name: name,
          selected_ci_sys_id: sysId,
          asset_tag: configurationItem,
          configurationItem,
          configurationItemDisplay: configurationItem,
          configurationItemValue: sysId
        });
