  // Assistant/application/ep/links.js
  var PANEL_ID = "sn-ep-links-panel";
  var ROOT_ATTR = "data-sn-assistant-root";
  function buildEpLinkContext(context = {}) {
    return {
      ticketNumber: cleanText(context.ticketNumber || context.recordNumber),
      sysId: cleanText(context.sysId),
      table: cleanText(context.table),
      configurationItem: cleanText(context.configurationItem || context.configurationItemDisplay),
      requestedFor: cleanText(context.requestedFor) || cleanText(context.requested_for) || cleanText(context.user?.fullName) || cleanText(context.user?.email)
    };
  }
  function buildDefaultLinks(linkCtx) {
    const links = [];
    const { ticketNumber, sysId, table } = linkCtx;
    if (table && sysId) {
      links.push({
        id: "_sn_record",
        label: `Open ${ticketNumber || table} in ServiceNow`,
        url: `/${table}.do?sys_id=${encodeURIComponent(sysId)}`
      });
    }
    if (ticketNumber) {
      links.push({
        id: "_sn_search",
        label: `Search "${ticketNumber}" in ServiceNow`,
        url: `/textsearch.do?sysparm_search=${encodeURIComponent(ticketNumber)}`
      });
    }
    return links;
  }
  function renderLinkItem(link) {
    const safeHref = sanitizeUrl(link.url);
    if (!safeHref) return "";
    return `
    <a
      class="sn-ep-links__item"
      href="${escapeHtml(safeHref)}"
      target="_blank"
      rel="noopener noreferrer"
      title="${escapeHtml(safeHref)}"
    >
      <span class="sn-ep-links__icon" aria-hidden="true">\u2197</span>
      <span class="sn-ep-links__label">${escapeHtml(link.label)}</span>
    </a>
  `;
  }
  function sanitizeUrl(rawUrl) {
    const value = cleanText(rawUrl);
    if (!value) return "";
    if (value.startsWith("/")) return value;
    if (/^(https?:|mailto:|tel:)/i.test(value)) return value;
    return "";
  }
  function buildPanel(hostDocument, linkCtx, defaultLinks, customLinks) {
    const existing = hostDocument.getElementById(PANEL_ID);
    if (existing) {
      existing.remove();
      return;
    }
    const panel = hostDocument.createElement("div");
    panel.id = PANEL_ID;
    panel.setAttribute(ROOT_ATTR, "true");
    panel.className = "sn-ep-links-root";
    const allCustomLinks = Array.isArray(customLinks) ? customLinks : [];
    const defaultSection = defaultLinks.length ? `
      <div class="sn-ep-links__section">
        <div class="sn-ep-links__section-label">Context links</div>
        ${defaultLinks.map(renderLinkItem).join("")}
      </div>
    ` : "";
    const customSection = allCustomLinks.length ? `
      <div class="sn-ep-links__section">
        <div class="sn-ep-links__section-label">My bookmarks</div>
        ${allCustomLinks.map(renderLinkItem).join("")}
      </div>
    ` : "";
    const emptyNote = !defaultLinks.length && !allCustomLinks.length ? `<div class="sn-assistant-note sn-assistant-note--empty">No links available. Add bookmarks in Settings \u2192 Launcher.</div>` : "";
    panel.innerHTML = `
    <div class="sn-ep-links__panel">
      <div class="sn-ep-links__header">
        <span class="sn-ep-links__title">EP Links${linkCtx.ticketNumber ? ` \xB7 ${escapeHtml(linkCtx.ticketNumber)}` : ""}</span>
        <button type="button" class="sn-assistant-mini-button sn-assistant-mini-button--danger" data-action="ep-links-close" title="Close" aria-label="Close EP Links">\xD7</button>
      </div>
      <div class="sn-ep-links__body">
        ${defaultSection}
        ${customSection}
        ${emptyNote}
        <div class="sn-ep-links__footer-hint">Links open in a new tab. Add bookmarks in Settings \u2192 Launcher.</div>
      </div>
    </div>
  `;
    panel.addEventListener("click", (event) => {
      if (event.target.closest('[data-action="ep-links-close"]')) {
        panel.remove();
      }
    });
    const ownerWindow = hostDocument.defaultView || window;
    ownerWindow.setTimeout(() => {
      const onOutside = (event) => {
        if (!panel.contains(event.target)) {
          panel.remove();
          ownerWindow.removeEventListener("click", onOutside, true);
        }
      };
      ownerWindow.addEventListener("click", onOutside, true);
    }, 0);
    (hostDocument.body || hostDocument.documentElement).appendChild(panel);
    sanitizeFloatingSurface(panel);
    const anchor = hostDocument.getElementById("sn-assistant-launcher")?.querySelector(".sn-ep");
    if (anchor) repositionSecondarySurfaces(hostDocument, anchor);
  }
  function openEpLinks({ hostDocument, context, settings, logger, showToast: showToast2 }) {
    const linkCtx = buildEpLinkContext(context);
    const defaultLinks = buildDefaultLinks(linkCtx);
    const customLinks = Array.isArray(settings?.customLinks) ? settings.customLinks : [];
    logger?.info("ep links opened", { ticketNumber: linkCtx.ticketNumber, customCount: customLinks.length });
    buildPanel(hostDocument, linkCtx, defaultLinks, customLinks);
  }

